window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-737bea62c1b75877"]={"versions": [{"id": "FIG-737bea62c1b75877", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_SupervisedEntity</code>) im Kontext des AUTOSAR Health Monitoring (Adaptive Platform). Das Diagramm modelliert die statische Struktur und Zerlegung einer überwachten Software-Einheit (<code>SupervisedEntity</code>) in zugehörige Kontrollpunkte (<code>Checkpoint</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und deren kompositionelle Beziehung:</p>\n<ul class=\"fig-list\"><li><code>SupervisedEntity</code>: Repräsentiert die überwachte logische Einheit mit den Attributen <code>- Name</code>, <code>- ID</code> und <code>- NumberOfInstances</code>.\n</li><li><code>Checkpoint</code>: Repräsentiert Kontrollpunkte innerhalb des Kontrollflusses der Entität mit den Attributen <code>- Name</code> und <code>- ID</code>.\n</li><li>Beziehung: Eine Kompositionsbeziehung (ausgefüllte Raute auf Seiten von <code>SupervisedEntity</code>) verbindet <code>SupervisedEntity</code> mit <code>Checkpoint</code>. Die Lebensdauer der <code>Checkpoint</code>-Instanzen ist an die übergeordnete <code>SupervisedEntity</code> gebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Klassendiagramm stellt die Abbildung keine dynamischen Sequenzen oder Laufzeitaufrufe dar. Auf architektonischer Ebene referenziert eine funktionale Komponente oder ein Prozess während der Ausführung die definierten Kontrollpunkte (<code>Checkpoint</code>), um Zustands- und Ablaufmeldungen an das Health Monitoring zur Auswertung von Alive-, Deadline- oder Logical-Supervision zu melden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell legt die Pflichtattribute für die Modellierung und Konfiguration von überwachten Einheiten fest. Entwickler müssen sicherstellen, dass jede <code>SupervisedEntity</code> eine eindeutige <code>ID</code>, einen Bezeichner (<code>Name</code>) sowie die Anzahl der Instanzen (<code>NumberOfInstances</code>) deklariert. Zugehörige <code>Checkpoint</code>-Definitionen existieren nur im Kontext ihrer <code>SupervisedEntity</code> und müssen über eine lokale <code>ID</code> und einen <code>Name</code> eindeutig adressierbar sein.</p>"}, {"id": "FIG-b2fb2cfcc43001a4", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_SupervisedEntity</code>) im Kontext des AUTOSAR Health Monitoring (Adaptive Platform). Das Diagramm modelliert die statische Struktur und Zerlegung einer überwachten Software-Einheit (<code>SupervisedEntity</code>) in zugehörige Kontrollpunkte (<code>Checkpoint</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und deren kompositionelle Beziehung:</p>\n<ul class=\"fig-list\"><li><code>SupervisedEntity</code>: Repräsentiert die überwachte logische Einheit mit den Attributen <code>- Name</code>, <code>- ID</code> und <code>- NumberOfInstances</code>.\n</li><li><code>Checkpoint</code>: Repräsentiert Kontrollpunkte innerhalb des Kontrollflusses der Entität mit den Attributen <code>- Name</code> und <code>- ID</code>.\n</li><li>Beziehung: Eine Kompositionsbeziehung (ausgefüllte Raute auf Seiten von <code>SupervisedEntity</code>) verbindet <code>SupervisedEntity</code> mit <code>Checkpoint</code>. Die Lebensdauer der <code>Checkpoint</code>-Instanzen ist an die übergeordnete <code>SupervisedEntity</code> gebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Klassendiagramm stellt die Abbildung keine dynamischen Sequenzen oder Laufzeitaufrufe dar. Auf architektonischer Ebene referenziert eine funktionale Komponente oder ein Prozess während der Ausführung die definierten Kontrollpunkte (<code>Checkpoint</code>), um Zustands- und Ablaufmeldungen an das Health Monitoring zur Auswertung von Alive-, Deadline- oder Logical-Supervision zu melden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell legt die Pflichtattribute für die Modellierung und Konfiguration von überwachten Einheiten fest. Entwickler müssen sicherstellen, dass jede <code>SupervisedEntity</code> eine eindeutige <code>ID</code>, einen Bezeichner (<code>Name</code>) sowie die Anzahl der Instanzen (<code>NumberOfInstances</code>) deklariert. Zugehörige <code>Checkpoint</code>-Definitionen existieren nur im Kontext ihrer <code>SupervisedEntity</code> und müssen über eine lokale <code>ID</code> und einen <code>Name</code> eindeutig adressierbar sein.</p>"}], "trans": [{"from": "FIG-737bea62c1b75877", "to": "FIG-b2fb2cfcc43001a4", "fr": "R1.5.1", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b2fb2cfcc43001a4", "to": "FIG-737bea62c1b75877", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
